10	/** Friendly copy for the `?error=` codes the Google OAuth routes bounce back. */
11	const GOOGLE_ERRORS: Record<string, string> = {
12	  google_unavailable: "Google sign-in isn't set up on this server yet. Use your email and password.",
13	  google_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
14	  google_cancelled: "Google sign-in was cancelled.",
15	  google_state: "That Google sign-in link expired or didn't match. Please try again.",
16	  google_unverified: "Your Google email isn't verified, so we can't sign you in with it.",
17	  google_error: "Couldn't finish signing in with Google. Please try again.",
18	  account_suspended: "This account is suspended.",
19	};
20	
21	/** Same convention as GOOGLE_ERRORS — see app/login/page.tsx's DISCORD_ERRORS. */
22	const DISCORD_ERRORS: Record<string, string> = {
23	  discord_unavailable: "Discord sign-in isn't set up on this server yet. Use your email and password.",
24	  discord_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
25	  discord_cancelled: "Discord connection cancelled.",
26	  discord_state: "That Discord sign-in link expired or didn't match. Please try again.",
27	  discord_unverified_email: "Your Discord account needs a verified email to sign up this way. Verify it on Discord, or create a Nxeon account normally and connect Discord from Settings afterward.",
28	  discord_email_taken: "An account with this email already exists. Log in normally, then connect Discord from Settings.",
29	  discord_suspended: "This account is suspended.",
30	  discord_error: "Couldn't finish signing in with Discord. Please try again.",
31	};
