33	export default async function RegisterPage({
34	  searchParams,
35	}: {
36	  searchParams: Promise<{ next?: string; error?: string }>;
37	}) {
38	  // Where the visitor was heading before hitting the sign-up wall. Carried
39	  // through the Google OAuth flow so first sign-in lands them where they meant to
40	  // go. Validated by `safeNext` — an unchecked `next` is an open redirect and
41	  // therefore a phishing primitive — so it is never trusted, here or in the action.
42	  const { next, error } = await searchParams;
43	  const dest = safeNext(next ?? null);
44	  // Only ever surface a message from our own fixed map — never echo the raw
45	  // query value into the page.
46	  const googleError = error ? GOOGLE_ERRORS[error] : undefined;
47	  const discordError = error ? DISCORD_ERRORS[error] : undefined;
48	  const discordEnabled = await discordOauthConfigured();
49	
50	  // Already signed in? Then this page is a waypoint: send them onward instead of
51	  // asking a paying customer to authenticate again.
52	  const user = await currentUser();
53	  if (user) redirect(dest ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));
54	
55	  return (
56	    <AuthShell
57	      heading="Create your account"
58	      sub="Deploy your first server in under a minute."
59	      // Two of these three were untrue. "No credit card required to get started"
60	      // implied a free first server — free deploys are admin-only, and a customer
61	      // with a $0 wallet gets "Insufficient balance. Top up your wallet first."
62	      // And "18+ OS images" was a hardcode the live catalogue passed long ago:
63	      // the homepage counts the same catalogue and renders 31+. A number nothing
64	      // computes goes stale by default, so this states the capability instead.
65	      bullets={[
66	        "Free to create — you pay when you deploy",
67	        "One-click OS images, control panels and apps",
68	        "Pay monthly, cancel anytime",
69	      ]}
70	    >
71	      <ReferralCapture />
72	      <RegisterForm
73	        next={dest ?? undefined}
74	        googleEnabled={googleOauthConfigured()}
75	        googleError={googleError}
76	        discordEnabled={discordEnabled}
77	        discordError={discordError}
78	      />
79	    </AuthShell>
80	  );
81	}
