1	import { NextRequest, NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { clientIp } from "@/lib/rate-limit";
4	import { hashIp } from "@/lib/coupon-order";
5	
6	/**
7	 * The REAL Creator Partner link: nxeon.cloud/partner/<code>. This is what a
8	 * partner is actually given to share — "acts like a coupon code or referral
9	 * link" (owner's spec) — and, unlike the older `/r/<code>` short link, it
10	 * RECORDS a real click (ReferralClick — an existing, previously-unused table:
11	 * see its own schema doc comment, "User.referralCode or ReferralPartner.code")
12	 * before setting the same `nxeon_ref` cookie and redirecting to /register.
13	 *
14	 * `/r/<code>` (app/r/[code]/route.ts) still works — the peer "refer a friend"
15	 * program uses it too and nothing depended on it changing — but this is the
16	 * primary route partners are handed, and the one place a partner's real click
17	 * count comes from (lib/partner-commission.ts partnerFunnel).
18	 *
19	 * DELIBERATELY still no gate on whether the code is a real/active partner
20	 * before recording the click or setting the cookie: a click is a click (even a
21	 * mistyped or since-paused code is real traffic worth counting), and — exactly
22	 * like `/r/<code>`'s own doc comment — `register` (lib/actions.ts) is what
23	 * actually validates the code before anything is attached or charged
24	 * differently. This route's only job is: record the click, translate the
25	 * short link into the cookie, redirect.
26	 */
27	
28	const REF_COOKIE = "nxeon_ref";
29	const REF_COOKIE_TTL_SECONDS = 60 * 60 * 24 * 30; // 30 days, matches ReferralCapture / app/r/[code]
30	
31	export async function GET(req: NextRequest, { params }: { params: Promise<{ code: string }> }) {
32	  const { code: rawCode } = await params;
33	
34	  // Redirect against the PUBLIC origin, not req.nextUrl.origin — see app/r/[code]/route.ts's
35	  // identical comment (behind the nginx proxy the request origin resolves to localhost).
36	  const publicOrigin = process.env.APP_URL ?? req.nextUrl.origin;
37	  const res = NextResponse.redirect(new URL("/register", publicOrigin), 302);
38	
39	  const code = rawCode.trim().toUpperCase().slice(0, 32);
40	  if (/^[A-Z0-9_-]+$/.test(code)) {
41	    res.cookies.set(REF_COOKIE, code, {
42	      path: "/",
43	      maxAge: REF_COOKIE_TTL_SECONDS,
44	      sameSite: "lax",
45	    });
46	    // Real click tracking — best-effort, never blocks or slows the redirect.
47	    // ipHash (not the raw IP) matches how every other per-visitor record on this
48	    // platform stores addresses (coupon/promo redemptions) — enough to dedupe or
49	    // investigate abuse without holding a raw IP against a marketing click.
50	    try {
51	      const ip = clientIp(req.headers);
52	      const ipHash = ip ? hashIp(ip, process.env.AUTH_SECRET ?? "nxeon") : null;
53	      await db.referralClick.create({
54	        data: {
55	          code,
56	          ipHash,
57	          referer: req.headers.get("referer")?.slice(0, 500) || null,
58	        },
59	      });
60	    } catch (e) {
61	      console.error("[partner-link] click record failed for", code, e);
62	    }
63	  }
64	  return res;
65	}
