1	import { NextRequest, NextResponse } from "next/server";
2	import { PROMO_CAMPAIGN_COOKIE, sanitizeCampaign } from "@/lib/promo-redemption";
3	
4	/**
5	 * Ad-bound entry link for the managed first-month-free promo.
6	 *
7	 *   /go/first-month-free?c=<campaign>
8	 *
9	 * Drops a short-lived `nx_promo_campaign` cookie carrying the (sanitized)
10	 * campaign tag, then 302-redirects the visitor into the funnel (/pricing). Every
11	 * order flow reads that cookie into the PromoRedemption's `campaign` field, so a
12	 * click that later converts is attributed to the ad that sent it — the same tag
13	 * the Meta/Google pixel already fires on, giving the admin Promotions page a
14	 * per-campaign conversion (renewed / total) view.
15	 *
16	 * The cookie is NOT httpOnly on purpose: it carries no secret, only an ad label,
17	 * and client-side pixel code may want to read it too. It is sanitized to a
18	 * bounded alnum-dash slug so nothing hostile can ride in on it, and expires in a
19	 * few days so a stale campaign tag never sticks to an unrelated later purchase.
20	 */
21	
22	const DEST: Record<string, string> = {
23	  "first-month-free": "/pricing",
24	};
25	
26	const CAMPAIGN_TTL_SECONDS = 60 * 60 * 24 * 3; // 3 days
27	
28	export async function GET(req: NextRequest, { params }: { params: Promise<{ slug: string }> }) {
29	  const { slug } = await params;
30	  const dest = DEST[slug];
31	  // Unknown slug: send them somewhere sensible rather than 404 an ad click.
32	  const target = dest ?? "/";
33	
34	  const campaign = sanitizeCampaign(req.nextUrl.searchParams.get("c"));
35	  // Redirect against the PUBLIC origin, not req.nextUrl.origin: behind the nginx
36	  // proxy the request origin resolves to http://localhost:3000, so an ad click
37	  // would 302 the visitor to localhost. APP_URL is the canonical public base.
38	  const publicOrigin = process.env.APP_URL ?? req.nextUrl.origin;
39	  const res = NextResponse.redirect(new URL(target, publicOrigin), 302);
40	
41	  // Only set the attribution cookie for a real promo slug with a campaign tag.
42	  if (dest && campaign) {
43	    res.cookies.set(PROMO_CAMPAIGN_COOKIE, campaign, {
44	      path: "/",
45	      maxAge: CAMPAIGN_TTL_SECONDS,
46	      sameSite: "lax",
47	    });
48	  }
49	  return res;
50	}
