26	
27	/* Data for the VPS deploy wizard.
28	 *
29	 * The one rule this file exists to keep: every number the wizard can display is
30	 * computed HERE, by the same functions that charge the card, and handed down
31	 * already worked out. The view prints; it never multiplies.
32	 *
33	 * `effectiveMonthlyCents` is built as a plan x term MATRIX rather than sent as a
34	 * rate plus a discount percent. Sending the percent would mean the browser does
35	 * `rate * (1 - pct)` — a second pricing formula, and the one that is on screen
36	 * when the customer decides. Terms are few and plans are few, so the matrix is
37	 * cheap and it cannot drift from `vpsTermPriceCents`.
38	 */
39	
40	export const dynamic = "force-dynamic";
41	
42	/* Icon per image, keyed off the platform's own `family` value rather than
43	   sniffing the display name. Control panels and applications have families too
44	   (cpanel, plesk, docker, ...), so one map serves all three tabs. */
45	const ICON_BY_FAMILY: Record<string, string> = {
46	  ubuntu: "ubuntu", debian: "debian", almalinux: "osA", rocky: "osC",
47	  arch: "arch", fedora: "osB", windows: "windows", centos: "osA",
48	  docker: "docker", wordpress: "cloud", node: "nginx", nginx: "nginx",
49	  mysql: "mysql", postgres: "postgres", redis: "redis",
50	  cpanel: "gear2", plesk: "gear2", webmin: "sliders", hestiacp: "sliders",
51	  cloudpanel: "sliders", cyberpanel: "sliders", aapanel: "sliders",
52	};
53	function osIcon(family: string, category: string): string {
54	  return ICON_BY_FAMILY[family?.toLowerCase()]
55	    ?? (category === "CONTROL_PANEL" ? "sliders" : category === "APPLICATION" ? "cube" : "linux");
56	}
57	
58	/* The plan-card promo badge's percent — the REAL gap between the intro monthly
59	 * rate and the regular monthly rate, so "X% off" can never show a number a
60	 * plan doesn't actually carry. Computed here (once, server-side) rather than
61	 * in the card component, same discipline as every other price on this page:
62	 * the view prints, it does not work anything out. Null (no badge) unless
63	 * `introCents` is a genuine, positive discount off `regularCents`. */
64	function introBadgePercent(regularCents: number, introCents: number | null): number | null {
65	  if (introCents == null || regularCents <= 0 || introCents >= regularCents) return null;
66	  return Math.max(1, Math.min(99, Math.round((1 - introCents / regularCents) * 100)));
67	}
