69	export default async function NxDeployPage() {
70	  const user = await requireUser();
71	
72	  // Exit-intent 25%-off popup eligibility (Feature: EXIT25). "First-time
73	  // customer" is the codebase's own established predicate for exactly this
74	  // kind of gate — zero non-free `Server` rows — already enforced identically
75	  // by `firstTimeOnly` coupon checks in lib/order.ts and
76	  // lib/coupon-redemption.ts. Resolved HERE, server-side, and threaded down as
77	  // a plain boolean prop: the deploy page is already a server component
78	  // reading `user`, so there is no reason to let the client decide something
79	  // this consequential on its own.
80	  const [isFirstTimeCustomer, exitIntentEnabled] = await Promise.all([
81	    db.server.count({ where: { userId: user.id, isFree: false } }).then((n) => n === 0),
82	    getSettingBool("exit_intent_enabled", true),
83	  ]);
84	
85	  // Real, per-customer eligibility for the first-month-free hosting promo —
86	  // NOT a display detail, the exact same advisory pre-check
87	  // lib/actions-hosting.ts runs before the atomic claim at charge time. The
88	  // wizard's hosting/email price was a flat, precomputed matrix with zero
89	  // per-user awareness (deliberately: "so there is no round-trip to make"),
90	  // which is why the promo's own plan-card badge ("First month free") and
91	  // the wizard's actual total disagreed — the matrix could not have known
92	  // whether THIS customer still qualifies. One extra check here, resolved
93	  // alongside the rest of this page's own data fetching.
94	  const hdrs = await headers();
95	  const hostingPromoIpHash = hashIp(clientIp(hdrs), process.env.AUTH_SECRET ?? "nxeon") || null;
96	  // Same "real signal, real fallback" resolution the display-currency path
97	  // already uses (lib/currency-display.ts) — a CDN/proxy country header first,
98	  // else the bundled geoip-lite dataset off the client IP, "" (falsy) if
99	  // neither resolves. Feeds `defaultRegionKey` below so a fresh order seeds
100	  // the region actually closest to this visitor rather than an arbitrary one.
101	  const visitorCountry = countryFromHeaders(hdrs) || countryFromRequestIp(hdrs) || null;
102	  const hostingPromoEligible =
103	    firstMonthFreeAppliesTo("HOSTING") &&
104	    (await firstMonthFreeEnabled()) &&
105	    (await firstMonthFreeEligible(user.id, hostingPromoIpHash));
106	
107	  const [plans, oses, nodes, gamePlans, hostingPlans, emailPlans, annualPct, diskPerGbCents, ipCents, backupCents] = await Promise.all([
108	    db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
109	    /* All three categories — the design's Server settings panel has a tab per
110	       category (Operating system / Control panels / Applications), which is
111	       exactly what ImageCategory already distinguishes. They are separated in
112	       the VIEW, not filtered out here: a game-server image is a real thing you
113	       can deploy, it just is not an answer to "pick an operating system". */
114	    /* Game images are EXCLUDED from the VPS wizard. They are real deployable
115	       images, but Nxeon sells game servers as their own product with their own
116	       plans, panel and pricing — offering "Minecraft Server" as a VPS
117	       application sells the same thing twice, at the wrong price, without the
118	       game panel. Identified by `family` against the platform's own
119	       GAME_FAMILIES registry rather than by matching "... Server" in a name. */
